const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'u = x / h' },
      { kind: 'text', payload: '瓶口基准线' },
      { kind: 'text', payload: 'u = 0' },
      { kind: 'text', payload: 'u = 1/2' },
      { kind: 'text', payload: 'u = 1' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'x = 0' },
      { kind: 'text', payload: 'x = h/2' },
      { kind: 'text', payload: 'x = h' },
      { kind: 'text', payload: 'u = 1 时木塞底部到达瓶口基准线' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport && input.viewport.widthDu ? input.viewport.widthDu : 960;
    var H = input.viewport && input.viewport.heightDu ? input.viewport.heightDu : 540;
    var formulaY = H * 0.07;
    var stageY = H * 0.18;
    var baseline = H * 0.56;
    var h = H * 0.24;
    var corkH = h;
    var neckDepth = H * 0.43;
    var margin = 32;
    var panelW = (W - 2 * margin) / 3;
    var centers = [margin + panelW * 0.5, margin + panelW * 1.5, margin + panelW * 2.5];
    var uVals = [0, 0.5, 1];
    var paths = [];
    var children = [];
    var labels = [];

    function addPath(id, commands, style) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (style) {
        for (var k in style) {
          if (Object.prototype.hasOwnProperty.call(style, k)) node[k] = style[k];
        }
      }
      children.push(node);
    }

    function roundRect(x, y, w, hh, r) {
      var k = r * 0.5522847498;
      return [
        ['M', x + r, y],
        ['L', x + w - r, y],
        ['C', x + w - r + k, y, x + w, y + r - k, x + w, y + r],
        ['L', x + w, y + hh - r],
        ['C', x + w, y + hh - r + k, x + w - r + k, y + hh, x + w - r, y + hh],
        ['L', x + r, y + hh],
        ['C', x + r - k, y + hh, x, y + hh - r + k, x, y + hh - r],
        ['L', x, y + r],
        ['C', x, y + r - k, x + r - k, y, x + r, y],
        ['Z']
      ];
    }

    function addLabel(text, x, y, opts) {
      var node = { type: 'label', x: x, y: y, text: text, fontSize: 16, fill: '#1f2d3d', align: 'center', baseline: 'middle' };
      if (opts) {
        for (var k in opts) {
          if (Object.prototype.hasOwnProperty.call(opts, k)) node[k] = opts[k];
        }
      }
      labels.push(node);
    }

    addPath('baseline', [
      ['M', margin, baseline],
      ['L', W - margin, baseline]
    ], { stroke: '#8b98a8', strokeWidth: 1.5, fill: 'none', strokeDasharray: '6 6' });

    for (var i = 0; i < 3; i++) {
      var cx = centers[i];
      var u = uVals[i];
      var y0 = baseline + h;
      var bottom = baseline + h * (1 - u);
      var top = bottom - corkH;

      addPath('neckL' + i, [
        ['M', cx - 54, baseline],
        ['L', cx - 54, baseline + neckDepth]
      ], { stroke: '#33475f', strokeWidth: 3, fill: 'none' });

      addPath('neckR' + i, [
        ['M', cx + 54, baseline],
        ['L', cx + 54, baseline + neckDepth]
      ], { stroke: '#33475f', strokeWidth: 3, fill: 'none' });

      addPath('lipL' + i, [
        ['M', cx - 64, baseline],
        ['L', cx - 48, baseline]
      ], { stroke: '#33475f', strokeWidth: 5, fill: 'none' });

      addPath('lipR' + i, [
        ['M', cx + 48, baseline],
        ['L', cx + 64, baseline]
      ], { stroke: '#33475f', strokeWidth: 5, fill: 'none' });

      addPath('ref' + i, [
        ['M', cx - 46, y0],
        ['L', cx + 46, y0]
      ], { stroke: '#9aa6b2', strokeWidth: 1, fill: 'none', strokeDasharray: '4 4' });

      addPath('cork' + i, roundRect(cx - 38, top, 76, corkH, 8), {
        fill: '#d8a15d',
        stroke: '#6b4a28',
        strokeWidth: 2
      });

      if (i === 0) {
        var xH = cx - 74;
        addPath('hBracket', [
          ['M', xH, baseline],
          ['L', xH, y0],
          ['M', xH - 5, baseline],
          ['L', xH + 5, baseline],
          ['M', xH - 5, y0],
          ['L', xH + 5, y0]
        ], { stroke: '#26354a', strokeWidth: 1.5, fill: 'none' });
      }

      var xX = cx + 76;
      if (u > 0) {
        addPath('xArrow' + i, visualSdk.arrow(xX, y0, xX, bottom, {}), {
          stroke: '#b23b2e',
          strokeWidth: 1.8,
          fill: 'none'
        });
        addPath('xTickA' + i, [
          ['M', xX - 5, y0],
          ['L', xX + 5, y0]
        ], { stroke: '#b23b2e', strokeWidth: 1.2, fill: 'none' });
        addPath('xTickB' + i, [
          ['M', xX - 5, bottom],
          ['L', xX + 5, bottom]
        ], { stroke: '#b23b2e', strokeWidth: 1.2, fill: 'none' });
      } else {
        addPath('xTick0' + i, [
          ['M', xX - 5, y0],
          ['L', xX + 5, y0]
        ], { stroke: '#b23b2e', strokeWidth: 1.2, fill: 'none' });
      }
    }

    addLabel('u = x / h', W / 2, formulaY, { fontSize: 22, fontWeight: 'bold', fill: '#1f2d3d' });
    addLabel('瓶口基准线', margin, baseline - 12, { fontSize: 14, align: 'left', fill: '#5b6878' });
    addLabel('u = 0', centers[0], stageY, { fontSize: 18 });
    addLabel('u = 1/2', centers[1], stageY, { fontSize: 18 });
    addLabel('u = 1', centers[2], stageY, { fontSize: 18 });
    addLabel('h', centers[0] - 84, baseline + h / 2, { fontSize: 16, align: 'right', fill: '#26354a' });
    addLabel('x = 0', centers[0] + 84, baseline + h, { fontSize: 14, align: 'left', fill: '#b23b2e' });
    addLabel('x = h/2', centers[1] + 84, baseline + h * 0.75, { fontSize: 14, align: 'left', fill: '#b23b2e' });
    addLabel('x = h', centers[2] + 84, baseline + h * 0.5, { fontSize: 14, align: 'left', fill: '#b23b2e' });
    addLabel('u = 1 时木塞底部到达瓶口基准线', W / 2, H - 20, { fontSize: 14, fill: '#4a5666' });

    for (var j = 0; j < labels.length; j++) children.push(labels[j]);

    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
